import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-for-vscode/getting-started.md","filePath":"zh/kimi-code-for-vscode/getting-started.md"}`),a={name:`kimi-code-for-vscode/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">VS Code 插件适配中</p><p>Kimi Code for VS Code 目前仅对旧版 Python CLI 用户开放新增安装。已安装插件的老用户升级新版 CLI 后仍可继续使用，其他 TS 版本 CLI 用户暂不支持安装。</p></div><p>Kimi Code for VS Code 是集成于 Visual Studio Code 的扩展插件。安装后，您可在编辑器内直接发起提问、审查代码 diff 并快速提交变更。插件能够读取您引用的文件内容，并通过可视化界面展示修改建议，经您确认后执行。整个流程由您掌控，同时显著提升开发效率。</p><p><img src="/code/docs/images/zh/vscode/kimi-code-showcase.jpeg" alt="Kimi Code VS Code"></p><p>本扩展在 VS Code 中提供了原生聊天面板，支持通过 <code>@</code> 符号引用文件或文件夹、<code>/</code> 命令执行项目扫描与上下文管理、diff 视图展示文件变更并支持回退操作，同时支持集成 MCP 服务器以调用外部工具。聊天面板可置于活动栏、侧边栏或独立标签页中。</p><h2 id="安装之前" tabindex="-1">安装之前 <a class="header-anchor" href="#安装之前" aria-label="Permalink to “安装之前”">​</a></h2><p>需拥有 Kimi 账号订阅或 Kimi API 密钥。</p><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h2><p>通过 <a href="vscode:extension/moonshot-ai.kimi-code" target="_blank" rel="noreferrer">VS Code Marketplace</a> 安装。</p><p>若安装后未显示扩展，请重启 VS Code 或在命令面板中执行 &quot;Developer: Reload Window&quot; (Mac: Cmd+Shift+P, Windows/Linux: Ctrl+Shift+P)。</p><h2 id="身份认证" tabindex="-1">身份认证 <a class="header-anchor" href="#身份认证" aria-label="Permalink to “身份认证”">​</a></h2><p>Kimi Code 支持两种认证模式：</p><p><strong>Kimi 账号模式</strong>：点击登录按钮，浏览器将打开授权页面，完成授权流程后返回 VS Code。</p><p><strong>API Key 模式</strong>：若已配置 API Key，可点击跳过登录。插件将在此模式下运行。</p><p><img src="/code/docs/images/zh/vscode/kimi-code-gear-icon.png" alt="Kimi Code Gear Icon"></p><p>您可随时通过齿轮图标切换认证模式。登出后将返回登录界面。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><p><strong>代码解读</strong>：输入 <code>@</code> 选择文件或文件夹，请求解释代码流程，可继续追问细节。</p><p><strong>重构</strong>：引用目标代码如 <code>@src/feature/</code>，请求重构方案，审查 diff 并选择性批准，必要时使用回退。</p><p><strong>调试</strong>：粘贴错误信息或堆栈跟踪，引用相关文件，请求诊断与修复，然后批准提议的变更。</p><p><strong>项目概览</strong>：引用文件夹如 <code>@src/services/</code>，请求模块地图或架构摘要，可继续询问依赖关系或薄弱环节。</p><h2 id="命令与快捷键" tabindex="-1">命令与快捷键 <a class="header-anchor" href="#命令与快捷键" aria-label="Permalink to “命令与快捷键”">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl+Shift+K</code> / <code>Cmd+Shift+K</code></td><td>聚焦 Kimi 输入框</td></tr><tr><td><code>Alt+K</code></td><td>插入当前文件引用</td></tr><tr><td><code>Ctrl+N</code> / <code>Cmd+N</code></td><td>新建对话（需启用 <code>kimi.enableNewConversationShortcut</code>，启用后将占用系统默认的&quot;新建文件&quot;快捷键）</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>在输入框中浏览输入历史</td></tr></tbody></table><p>在命令面板中输入 &quot;Kimi Code&quot; 可访问更多命令：在新标签页打开、在侧边栏打开、新建对话等。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-for-vscode/core-operations.html">核心操作</a> – 学习聊天面板用法、上下文管理与 diff 审查</li><li><a href="/code/docs/kimi-code-for-vscode/customization.html">定制化</a> – 探索 Skills、Hooks 与 MCP 扩展能力</li><li><a href="/code/docs/kimi-code-for-vscode/configuration.html">配置</a> – 自定义认证、模型与行为设置</li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};